 selected.append(z);author.append({'ordinal':n,'goalId':e['goalId'],'selectedAsset':bind(png),'actualOriginal360680Viewed':True,'notes':'Selected after actual model/phone inspection. No independent author approval; preserve every generation attempt and original review.'})
